import { spawnSync } from 'node:child_process'
import { chmodSync, cpSync, existsSync, mkdirSync, readdirSync, rmSync, statSync, writeFileSync } from 'node:fs'
import { dirname, join, resolve } from 'node:path'

import { UsageError, dataDir, readJson, walk } from './util.mjs'

/**
 * Disposable projects for the replay. Each is generated by this checkout's own CLI (`bin/sf.js`, so the
 * templates under test, not a released package), into a folder that is thrown away, with:
 *
 * - a scratch HOME, so no credential, global git config or agent login of the machine is in reach;
 * - an `npm` and an `npx` that do nothing, so generation installs no dependency and needs no network;
 * - every `.env` file removed afterwards (`.env.example` stays, it is a template).
 *
 * The recipes are data (`fixtures.json`); this file runs their steps.
 */
export const FIXTURE_ENV_ALLOW = ['PATH', 'LANG', 'LC_ALL', 'TMPDIR', 'TERM']

export const loadRecipes = (root) => readJson(join(dataDir(root), 'fixtures.json'))

/** The environment of every process a fixture step starts: an allowlist, a scratch HOME, no token of any kind. */
export function fixtureEnv(parent, { home, shims }) {
  const env = {}
  for (const name of FIXTURE_ENV_ALLOW) if (parent[name] !== undefined) env[name] = parent[name]
  env.PATH = `${shims}${parent.PATH ? `:${parent.PATH}` : ''}`
  env.HOME = home
  env.CI = '1'
  env.NO_COLOR = '1'
  env.GIT_CONFIG_NOSYSTEM = '1'
  return env
}

function makeShims(dir) {
  mkdirSync(dir, { recursive: true })
  for (const name of ['npm', 'npx']) {
    const path = join(dir, name)
    writeFileSync(path, '#!/bin/sh\n# A replay fixture installs no dependency.\nexit 0\n')
    chmodSync(path, 0o755)
  }
  return dir
}

function run(command, args, { cwd, env, what }) {
  const result = spawnSync(command, args, { cwd, env, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
  if (result.status !== 0) {
    throw new UsageError(`fixture step failed (${what}): ${command} ${args.join(' ')}\n${(result.stderr || result.stdout || String(result.error)).trim().slice(-2000)}`)
  }
  return result
}

/** `.env` and `.env.<anything>` except the `.example` and `.sample` templates. Returns what it removed. */
export function scrubEnvFiles(dir) {
  const removed = []
  for (const rel of walk(dir)) {
    const name = rel.split('/').at(-1)
    if (/^\.env(\..+)?$/.test(name) && !/\.(example|sample)$/.test(name)) {
      rmSync(join(dir, rel), { force: true })
      removed.push(rel)
    }
  }
  return removed
}

const setPath = (object, path, value) => {
  const keys = path.split('.')
  let node = object
  for (const key of keys.slice(0, -1)) node = node[key] ??= {}
  node[keys.at(-1)] = value
}

function gitTracked(root, prefixes) {
  const result = spawnSync('git', ['ls-files', '-z', '--', ...prefixes], { cwd: root, encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 })
  if (result.status !== 0) throw new UsageError(`git ls-files failed in ${root}`)
  return result.stdout.split('\0').filter(Boolean)
}

/**
 * Generate the fixtures `ids` under `outDir`; returns `{ id: { dir, removedEnvFiles } }` where `dir` is the folder
 * the agent starts in. Needs `npm run build` first: the recipes call this checkout's `bin/sf.js`.
 */
export function generateFixtures(root, ids, outDir, { env: parentEnv = process.env, log = () => {} } = {}) {
  const recipes = loadRecipes(root).fixtures
  const sf = join(root, 'bin', 'sf.js')
  const needsCli = ids.some((id) => (recipes[id]?.steps ?? []).some((step) => step.op === 'sf'))
  if (needsCli && !existsSync(join(root, 'dist', 'index.js'))) throw new UsageError('this checkout is not built: run `npm run build`, then generate the fixtures again')

  const scratch = join(outDir, '.scratch')
  const home = join(scratch, 'home')
  mkdirSync(home, { recursive: true })
  const shims = makeShims(join(scratch, 'shims'))
  const env = fixtureEnv(parentEnv, { home, shims })
  const out = {}

  for (const id of ids) {
    const recipe = recipes[id]
    if (!recipe) throw new UsageError(`no fixture recipe named ${id} (see fixtures.json)`)
    const base = join(outDir, id)
    rmSync(base, { recursive: true, force: true })
    mkdirSync(base, { recursive: true })
    log(`fixture ${id}`)
    for (const step of recipe.steps) {
      const dir = resolve(base, step.dir ?? '.')
      switch (step.op) {
        case 'mkdir':
          mkdirSync(dir, { recursive: true })
          break
        case 'git-init':
          mkdirSync(dir, { recursive: true })
          run('git', ['init', '-q', '-b', 'main'], { cwd: dir, env, what: `${id}: git init` })
          break
        case 'sf':
          run(process.execPath, [sf, ...step.args], { cwd: dir, env, what: `${id}: sf ${step.args[0]}` })
          break
        case 'copy-skill': {
          const source = join(root, step.from)
          const target = join(dir, step.to)
          cpSync(source, target, { recursive: true })
          for (const executable of step.executable ?? []) chmodSync(join(target, executable), 0o755)
          break
        }
        case 'json-set': {
          const file = join(dir, step.file)
          const doc = readJson(file)
          for (const [path, value] of Object.entries(step.set)) setPath(doc, path, value)
          writeFileSync(file, `${JSON.stringify(doc, null, 2)}\n`)
          break
        }
        case 'write':
          mkdirSync(dirname(join(dir, step.path)), { recursive: true })
          writeFileSync(join(dir, step.path), step.content)
          break
        case 'copy-tracked': {
          for (const rel of gitTracked(root, step.paths)) {
            if (/(^|\/)\.env(\.|$)/.test(rel) && !/\.(example|sample)$/.test(rel)) continue
            if (!existsSync(join(root, rel)) || !statSync(join(root, rel)).isFile()) continue
            mkdirSync(dirname(join(dir, rel)), { recursive: true })
            cpSync(join(root, rel), join(dir, rel))
          }
          break
        }
        default:
          throw new UsageError(`fixture ${id}: unknown step ${step.op}`)
      }
    }
    const removedEnvFiles = scrubEnvFiles(base)
    const agentDir = resolve(base, recipe.agentDir ?? '.')
    if (!existsSync(agentDir) || readdirSync(agentDir).length === 0) throw new UsageError(`fixture ${id} generated nothing in ${agentDir}`)
    out[id] = { dir: agentDir, removedEnvFiles }
  }
  rmSync(scratch, { recursive: true, force: true })
  return out
}

/** Does a generated fixture hold anything an agent must never see: an env file, a credentials folder, a key? */
export function findForbiddenFiles(dir) {
  return walk(dir).filter((rel) => {
    const name = rel.split('/').at(-1)
    return (/^\.env(\..+)?$/.test(name) && !/\.(example|sample)$/.test(name)) || rel.split('/').includes('credentials') || name.endsWith('.pem') || name.startsWith('id_rsa')
  })
}
